<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Submission details · UIU Recruitment Portal Admin</title><?php $adminSection='submissions'; ?><?= $this->include('admin/_styles') ?><style>.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:20px}.summary .admin-card{padding:16px}.label{font-size:11px;color:#798196;text-transform:uppercase}.value{font-size:18px;font-weight:700;margin-top:7px}.question{margin:14px 0}.question-head{display:flex;justify-content:space-between;gap:15px;color:#798196;font-size:12px}.prompt{font-size:16px;font-weight:700;margin:8px 0}.answer{padding:13px;border-radius:8px;background:#f7f9fc;white-space:pre-wrap;line-height:1.5}.unanswered{color:#a36b1b;background:#fff7e5}.back{color:#168fd4;font-size:13px}@media(max-width:750px){.summary{grid-template-columns:repeat(2,1fr)}}</style></head><body><div class="admin-app"><?php $username=session()->get('admin_username');$usertype=session()->get('admin_usertype'); ?><?= $this->include('admin/_sidebar') ?><main class="admin-main"><header class="admin-topbar"><div class="admin-top-title">Submission details</div><div class="admin-search">⌕ <span>Search...</span><span style="margin-left:auto">⌘ K</span></div><div class="admin-pill">✦ AI insights</div><div style="font-size:20px;color:#778092">☼</div></header><div class="admin-content"><a class="back" href="<?= site_url('admin/submissions') ?>">← Back to submissions</a><div class="admin-heading"><div><h1><?= esc($submission['applicant_name'] ?: 'Unknown applicant') ?></h1><p><?= esc($submission['applicant_id']) ?><?php if ($submission['applicant_position']): ?> · <?= esc($submission['applicant_position']) ?><?php endif; ?></p></div><span class="admin-btn" style="background:#eaf8ef;color:#187345"><?= esc($submission['status']) ?></span></div><div class="summary"><div class="admin-card"><div class="label">Reference</div><div class="value" style="font-size:14px"><?= esc($submission['reference']) ?></div></div><div class="admin-card"><div class="label">Answered</div><div class="value"><?= esc($submission['answered_count']) ?> / <?= esc($submission['total_count']) ?></div></div><div class="admin-card"><div class="label">Current score</div><div class="value"><?= $submission['score'] !== null ? esc($submission['score']) . ' / ' . esc($submission['max_score']) : 'Not marked' ?></div></div><div class="admin-card"><div class="label">Submitted</div><div class="value" style="font-size:14px"><?= esc($submission['submitted_at']) ?></div></div></div><section class="admin-card"><div style="font-size:18px;font-weight:700;margin-bottom:16px">Question-wise answers</div><?php foreach($questions as $index=>$question): ?><article class="question"><div class="question-head"><span>Question <?= $index+1 ?> · <?= esc($question['type']) ?></span><span><?= esc($question['points']) ?> points</span></div><div class="prompt"><?= esc($question['prompt']) ?></div><div class="answer <?= $question['answer'] === null || $question['answer'] === '' ? 'unanswered' : '' ?>"><?= $question['answer'] === null || $question['answer'] === '' ? 'Not answered' : esc(is_array($question['answer']) ? implode(', ', $question['answer']) : (string) $question['answer']) ?></div></article><?php endforeach; ?></section><?php if ($submission['marker_notes']): ?><section class="admin-card" style="margin-top:20px"><strong>Reviewer notes</strong><p><?= nl2br(esc($submission['marker_notes'])) ?></p></section><?php endif; ?></div></main></div></body></html>
